const TWO_DIGIT_UNITS=new Set(["$/MMBtu","$/dmtu"]);function digitsFor(unit){return TWO_DIGIT_UNITS.has(unit)?2:1}function fmt(value,digits=1){if(value==null||Number.isNaN(value))return"n/a";return value.toLocaleString("en-US",{minimumFractionDigits:digits,maximumFractionDigits:digits})}function signed(value){if(value==null||Number.isNaN(value))return"n/a";return`${value>=0?"+":""}${value.toFixed(1)}%`}const MONTHS=["January","February","March","April","May","June","July","August","September","October","November","December"];function monthLabel(period){if(!period)return"n/a";const[y,m]=period.split("-").map(Number);return`${MONTHS[m-1]} ${y}`}function shiftMonth(period,months){const[y,m]=period.split("-").map(Number);const index=y*12+(m-1)+months;return`${Math.floor(index/12)}-${String(index%12+1).padStart(2,"0")}`}function shortMonth(period){const[y,m]=period.split("-").map(Number);return`${MONTHS[m-1].slice(0,3)} ${y}`}const UNIT_LABELS={"transits/day":"transits per day",index:""};function unitLabel(unit){if(!unit)return"";return UNIT_LABELS[unit]??unit.replace(/^\$\//,"USD/")}function legendLabel(row){return row.name.split(" \u2014 ")[0].replace(/ \([^()]*= 100\)$/,"").replace(/ price index$/i,"")}function monthDate(period){const[y,m]=period.split("-").map(Number);return new Date(y,m-1,1)}function dayLabel(day){const d=typeof day==="string"?new Date(`${day}T00:00:00`):day;return`${d.getDate()} ${MONTHS[d.getMonth()].slice(0,3)} ${d.getFullYear()}`}function monthYearLabel(d){return`${MONTHS[d.getMonth()].slice(0,3)} ${d.getFullYear()}`}export{dayLabel,digitsFor,fmt,legendLabel,monthDate,monthLabel,monthYearLabel,shiftMonth,shortMonth,signed,unitLabel};
